-- Raja Scout Intelligence — PostgreSQL schema (generated by `python -m app.cli schema-sql`)

CREATE TABLE login_attempts (
	id SERIAL NOT NULL, 
	key VARCHAR(300) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id)
);

CREATE INDEX ix_login_attempts_created_at ON login_attempts (created_at);
CREATE INDEX ix_login_attempts_key ON login_attempts (key);

CREATE TABLE organizations (
	id SERIAL NOT NULL, 
	slug VARCHAR(60) NOT NULL, 
	name VARCHAR(200) NOT NULL, 
	short_name VARCHAR(40), 
	country VARCHAR(100), 
	primary_language VARCHAR(5) NOT NULL, 
	currency VARCHAR(3) NOT NULL, 
	timezone VARCHAR(60) NOT NULL, 
	logo_data_url TEXT, 
	settings JSON NOT NULL, 
	is_demo BOOLEAN NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id)
);

CREATE UNIQUE INDEX ix_organizations_slug ON organizations (slug);

CREATE TABLE users (
	id SERIAL NOT NULL, 
	email VARCHAR(255) NOT NULL, 
	full_name VARCHAR(200) NOT NULL, 
	hashed_password VARCHAR(255) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	is_platform_admin BOOLEAN NOT NULL, 
	token_version INTEGER NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	last_login_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id)
);

CREATE UNIQUE INDEX ix_users_email ON users (email);

CREATE TABLE audit_logs (
	id SERIAL NOT NULL, 
	organization_id INTEGER, 
	user_id INTEGER, 
	user_email VARCHAR(255), 
	action VARCHAR(80) NOT NULL, 
	entity_type VARCHAR(60), 
	entity_id INTEGER, 
	details JSON, 
	ip_address VARCHAR(64), 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(organization_id) REFERENCES organizations (id) ON DELETE CASCADE, 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX ix_audit_logs_action ON audit_logs (action);
CREATE INDEX ix_audit_logs_created_at ON audit_logs (created_at);
CREATE INDEX ix_audit_logs_entity_type ON audit_logs (entity_type);
CREATE INDEX ix_audit_logs_organization_id ON audit_logs (organization_id);

CREATE TABLE data_sources (
	id SERIAL NOT NULL, 
	organization_id INTEGER, 
	name VARCHAR(200) NOT NULL, 
	source_type VARCHAR(40) NOT NULL, 
	url VARCHAR(500), 
	license_notes TEXT, 
	is_fictional BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(organization_id) REFERENCES organizations (id) ON DELETE CASCADE
);

CREATE INDEX ix_data_sources_organization_id ON data_sources (organization_id);
CREATE UNIQUE INDEX uq_data_source_org_name ON data_sources (organization_id, name) WHERE organization_id IS NOT NULL;
CREATE UNIQUE INDEX uq_data_source_shared_name ON data_sources (name) WHERE organization_id IS NULL;

CREATE TABLE invitations (
	id SERIAL NOT NULL, 
	organization_id INTEGER NOT NULL, 
	email VARCHAR(255) NOT NULL, 
	role VARCHAR(40) NOT NULL, 
	region VARCHAR(120), 
	token_hash VARCHAR(64) NOT NULL, 
	expires_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	accepted_at TIMESTAMP WITH TIME ZONE, 
	revoked_at TIMESTAMP WITH TIME ZONE, 
	created_by_id INTEGER, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(organization_id) REFERENCES organizations (id) ON DELETE CASCADE, 
	UNIQUE (token_hash), 
	FOREIGN KEY(created_by_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX ix_invitations_organization_id ON invitations (organization_id);

CREATE TABLE leagues (
	id SERIAL NOT NULL, 
	organization_id INTEGER, 
	name VARCHAR(200) NOT NULL, 
	country VARCHAR(100) NOT NULL, 
	tier INTEGER, 
	strength_coefficient FLOAT, 
	coefficient_source VARCHAR(300), 
	is_fictional BOOLEAN NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(organization_id) REFERENCES organizations (id) ON DELETE CASCADE
);

CREATE INDEX ix_leagues_organization_id ON leagues (organization_id);
CREATE UNIQUE INDEX uq_league_org ON leagues (organization_id, name, country) WHERE organization_id IS NOT NULL;
CREATE UNIQUE INDEX uq_league_shared ON leagues (name, country) WHERE organization_id IS NULL;

CREATE TABLE memberships (
	id SERIAL NOT NULL, 
	user_id INTEGER NOT NULL, 
	organization_id INTEGER NOT NULL, 
	role VARCHAR(40) NOT NULL, 
	region VARCHAR(120), 
	is_active BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_membership_user_org UNIQUE (user_id, organization_id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, 
	FOREIGN KEY(organization_id) REFERENCES organizations (id) ON DELETE CASCADE
);

CREATE INDEX ix_memberships_organization_id ON memberships (organization_id);
CREATE INDEX ix_memberships_user_id ON memberships (user_id);

CREATE TABLE password_reset_tokens (
	id SERIAL NOT NULL, 
	user_id INTEGER NOT NULL, 
	token_hash VARCHAR(64) NOT NULL, 
	expires_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	used_at TIMESTAMP WITH TIME ZONE, 
	created_by_id INTEGER, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, 
	UNIQUE (token_hash), 
	FOREIGN KEY(created_by_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX ix_password_reset_tokens_user_id ON password_reset_tokens (user_id);

CREATE TABLE recruitment_budgets (
	id SERIAL NOT NULL, 
	organization_id INTEGER NOT NULL, 
	season VARCHAR(20) NOT NULL, 
	transfer_budget INTEGER NOT NULL, 
	wage_budget INTEGER, 
	notes TEXT, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_budget_org_season UNIQUE (organization_id, season), 
	FOREIGN KEY(organization_id) REFERENCES organizations (id) ON DELETE CASCADE
);

CREATE INDEX ix_recruitment_budgets_organization_id ON recruitment_budgets (organization_id);

CREATE TABLE clubs (
	id SERIAL NOT NULL, 
	organization_id INTEGER, 
	name VARCHAR(200) NOT NULL, 
	country VARCHAR(100) NOT NULL, 
	league_id INTEGER, 
	is_fictional BOOLEAN NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(organization_id) REFERENCES organizations (id) ON DELETE CASCADE, 
	FOREIGN KEY(league_id) REFERENCES leagues (id) ON DELETE SET NULL
);

CREATE INDEX ix_clubs_organization_id ON clubs (organization_id);
CREATE UNIQUE INDEX uq_club_org ON clubs (organization_id, name, country) WHERE organization_id IS NOT NULL;
CREATE UNIQUE INDEX uq_club_shared ON clubs (name, country) WHERE organization_id IS NULL;

CREATE TABLE players (
	id SERIAL NOT NULL, 
	organization_id INTEGER, 
	full_name VARCHAR(200) NOT NULL, 
	known_as VARCHAR(120), 
	date_of_birth DATE, 
	nationality VARCHAR(100) NOT NULL, 
	second_nationality VARCHAR(100), 
	current_club_id INTEGER, 
	primary_position VARCHAR(4) NOT NULL, 
	secondary_positions JSON, 
	height_cm INTEGER, 
	weight_kg INTEGER, 
	preferred_foot VARCHAR(10), 
	contract_expiry DATE, 
	data_source_id INTEGER, 
	source_reference VARCHAR(300), 
	is_fictional BOOLEAN NOT NULL, 
	created_by_id INTEGER, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	last_updated TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(organization_id) REFERENCES organizations (id) ON DELETE CASCADE, 
	FOREIGN KEY(current_club_id) REFERENCES clubs (id) ON DELETE SET NULL, 
	FOREIGN KEY(data_source_id) REFERENCES data_sources (id), 
	FOREIGN KEY(created_by_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX ix_players_club ON players (current_club_id);
CREATE INDEX ix_players_full_name ON players (full_name);
CREATE INDEX ix_players_is_fictional ON players (is_fictional);
CREATE INDEX ix_players_nationality ON players (nationality);
CREATE INDEX ix_players_organization_id ON players (organization_id);
CREATE INDEX ix_players_primary_position ON players (primary_position);

CREATE TABLE match_videos (
	id SERIAL NOT NULL, 
	organization_id INTEGER NOT NULL, 
	player_id INTEGER NOT NULL, 
	match_date DATE, 
	competition VARCHAR(200), 
	home_team VARCHAR(200) NOT NULL, 
	away_team VARCHAR(200) NOT NULL, 
	video_url VARCHAR(1000) NOT NULL, 
	license_type VARCHAR(40) NOT NULL, 
	rights_holder VARCHAR(200) NOT NULL, 
	license_confirmed BOOLEAN NOT NULL, 
	is_full_match BOOLEAN NOT NULL, 
	duration_minutes INTEGER, 
	notes TEXT, 
	created_by_id INTEGER, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_match_video_id_org UNIQUE (id, organization_id), 
	FOREIGN KEY(organization_id) REFERENCES organizations (id) ON DELETE CASCADE, 
	FOREIGN KEY(player_id) REFERENCES players (id) ON DELETE CASCADE, 
	FOREIGN KEY(created_by_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX ix_match_videos_organization_id ON match_videos (organization_id);
CREATE INDEX ix_match_videos_player_id ON match_videos (player_id);

CREATE TABLE pipeline_entries (
	id SERIAL NOT NULL, 
	organization_id INTEGER NOT NULL, 
	player_id INTEGER NOT NULL, 
	stage VARCHAR(30) NOT NULL, 
	priority VARCHAR(10) NOT NULL, 
	target_position VARCHAR(4), 
	assigned_scout_id INTEGER, 
	rejection_reason TEXT, 
	created_by_id INTEGER, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_pipeline_org_player UNIQUE (organization_id, player_id), 
	CONSTRAINT uq_pipeline_entry_id_org UNIQUE (id, organization_id), 
	FOREIGN KEY(organization_id) REFERENCES organizations (id) ON DELETE CASCADE, 
	FOREIGN KEY(player_id) REFERENCES players (id) ON DELETE CASCADE, 
	FOREIGN KEY(assigned_scout_id) REFERENCES users (id) ON DELETE SET NULL, 
	FOREIGN KEY(created_by_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX ix_pipeline_entries_organization_id ON pipeline_entries (organization_id);
CREATE INDEX ix_pipeline_entries_player_id ON pipeline_entries (player_id);
CREATE INDEX ix_pipeline_entries_stage ON pipeline_entries (stage);

CREATE TABLE player_assessments (
	id SERIAL NOT NULL, 
	organization_id INTEGER NOT NULL, 
	player_id INTEGER NOT NULL, 
	tactical_role VARCHAR(80), 
	physical_profile TEXT, 
	estimated_fee INTEGER, 
	fee_estimate_source VARCHAR(300), 
	salary_expectation INTEGER, 
	availability VARCHAR(30) NOT NULL, 
	agent_name VARCHAR(200), 
	notes TEXT, 
	updated_by_id INTEGER, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_assessment_org_player UNIQUE (organization_id, player_id), 
	FOREIGN KEY(organization_id) REFERENCES organizations (id) ON DELETE CASCADE, 
	FOREIGN KEY(player_id) REFERENCES players (id) ON DELETE CASCADE, 
	FOREIGN KEY(updated_by_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX ix_player_assessments_organization_id ON player_assessments (organization_id);
CREATE INDEX ix_player_assessments_player_id ON player_assessments (player_id);

CREATE TABLE player_season_stats (
	id SERIAL NOT NULL, 
	organization_id INTEGER, 
	player_id INTEGER NOT NULL, 
	season VARCHAR(20) NOT NULL, 
	league_id INTEGER, 
	club_name VARCHAR(200), 
	appearances INTEGER, 
	starts INTEGER, 
	minutes INTEGER, 
	team_matches INTEGER, 
	goals INTEGER, 
	non_penalty_goals INTEGER, 
	assists INTEGER, 
	shots INTEGER, 
	shots_on_target INTEGER, 
	xg FLOAT, 
	npxg FLOAT, 
	xa FLOAT, 
	key_passes INTEGER, 
	passes_attempted INTEGER, 
	passes_completed INTEGER, 
	progressive_passes INTEGER, 
	passes_final_third INTEGER, 
	long_passes_attempted INTEGER, 
	long_passes_completed INTEGER, 
	crosses_attempted INTEGER, 
	crosses_completed INTEGER, 
	progressive_carries INTEGER, 
	dribbles_attempted INTEGER, 
	dribbles_completed INTEGER, 
	touches_in_box INTEGER, 
	tackles INTEGER, 
	tackles_won INTEGER, 
	interceptions INTEGER, 
	recoveries INTEGER, 
	defensive_duels INTEGER, 
	defensive_duels_won INTEGER, 
	aerial_duels INTEGER, 
	aerial_duels_won INTEGER, 
	clearances INTEGER, 
	blocks INTEGER, 
	pressures INTEGER, 
	fouls_committed INTEGER, 
	yellow_cards INTEGER, 
	red_cards INTEGER, 
	saves INTEGER, 
	shots_on_target_faced INTEGER, 
	goals_conceded INTEGER, 
	clean_sheets INTEGER, 
	psxg_faced FLOAT, 
	data_source_id INTEGER, 
	is_fictional BOOLEAN NOT NULL, 
	last_updated TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_stats_player_season_src UNIQUE (player_id, season, league_id, data_source_id), 
	FOREIGN KEY(organization_id) REFERENCES organizations (id) ON DELETE CASCADE, 
	FOREIGN KEY(player_id) REFERENCES players (id) ON DELETE CASCADE, 
	FOREIGN KEY(league_id) REFERENCES leagues (id) ON DELETE SET NULL, 
	FOREIGN KEY(data_source_id) REFERENCES data_sources (id)
);

CREATE INDEX ix_player_season_stats_organization_id ON player_season_stats (organization_id);
CREATE INDEX ix_player_season_stats_player_id ON player_season_stats (player_id);

CREATE TABLE scouting_reports (
	id SERIAL NOT NULL, 
	organization_id INTEGER NOT NULL, 
	player_id INTEGER NOT NULL, 
	author_id INTEGER, 
	title VARCHAR(300) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	sections JSON NOT NULL, 
	recommendation VARCHAR(40), 
	potential_rating INTEGER, 
	risk_level VARCHAR(10), 
	auto_generated BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(organization_id) REFERENCES organizations (id) ON DELETE CASCADE, 
	FOREIGN KEY(player_id) REFERENCES players (id) ON DELETE CASCADE, 
	FOREIGN KEY(author_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX ix_scouting_reports_organization_id ON scouting_reports (organization_id);
CREATE INDEX ix_scouting_reports_player_id ON scouting_reports (player_id);

CREATE TABLE match_reports (
	id SERIAL NOT NULL, 
	organization_id INTEGER NOT NULL, 
	player_id INTEGER NOT NULL, 
	video_id INTEGER, 
	scout_id INTEGER, 
	observation_type VARCHAR(30) NOT NULL, 
	match_date DATE, 
	opponent VARCHAR(200), 
	competition VARCHAR(200), 
	position_played VARCHAR(4), 
	minutes_observed INTEGER, 
	technical_rating INTEGER, 
	tactical_rating INTEGER, 
	physical_rating INTEGER, 
	mental_rating INTEGER, 
	overall_rating INTEGER, 
	technical_notes TEXT, 
	tactical_notes TEXT, 
	physical_notes TEXT, 
	mental_notes TEXT, 
	strengths TEXT, 
	weaknesses TEXT, 
	summary TEXT, 
	recommendation VARCHAR(40), 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(organization_id) REFERENCES organizations (id) ON DELETE CASCADE, 
	FOREIGN KEY(player_id) REFERENCES players (id) ON DELETE CASCADE, 
	FOREIGN KEY(video_id) REFERENCES match_videos (id) ON DELETE SET NULL, 
	FOREIGN KEY(scout_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX ix_match_reports_organization_id ON match_reports (organization_id);
CREATE INDEX ix_match_reports_player_id ON match_reports (player_id);

CREATE TABLE pipeline_events (
	id SERIAL NOT NULL, 
	organization_id INTEGER NOT NULL, 
	entry_id INTEGER NOT NULL, 
	from_stage VARCHAR(30), 
	to_stage VARCHAR(30) NOT NULL, 
	note TEXT, 
	user_id INTEGER, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT fk_event_entry_same_org FOREIGN KEY(entry_id, organization_id) REFERENCES pipeline_entries (id, organization_id) ON DELETE CASCADE, 
	FOREIGN KEY(organization_id) REFERENCES organizations (id) ON DELETE CASCADE, 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX ix_pipeline_events_entry_id ON pipeline_events (entry_id);
CREATE INDEX ix_pipeline_events_organization_id ON pipeline_events (organization_id);

CREATE TABLE video_observations (
	id SERIAL NOT NULL, 
	organization_id INTEGER NOT NULL, 
	video_id INTEGER NOT NULL, 
	timestamp_seconds INTEGER NOT NULL, 
	category VARCHAR(40) NOT NULL, 
	phase VARCHAR(40), 
	assessment VARCHAR(10) NOT NULL, 
	technical_comment TEXT, 
	tactical_comment TEXT, 
	scout_id INTEGER, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT fk_observation_video_same_org FOREIGN KEY(video_id, organization_id) REFERENCES match_videos (id, organization_id) ON DELETE CASCADE, 
	FOREIGN KEY(organization_id) REFERENCES organizations (id) ON DELETE CASCADE, 
	FOREIGN KEY(scout_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX ix_video_observations_organization_id ON video_observations (organization_id);
CREATE INDEX ix_video_observations_video_id ON video_observations (video_id);

